inline uint8_t lookup(uint32_t code) {
    size_t low = 0, high = sizeof(entries) / sizeof(entries[0]);
    while (low < high) {
        const size_t middle = low + (high - low) / 2;
        if (entries[middle].code < code) low = middle + 1;
        else high = middle;
    }
    if (low < sizeof(entries) / sizeof(entries[0]) && entries[low].code == code)
        return entries[low].type;
    return code == 0x4553424Bu || code == 0x23232323u ? 0 : 1;
}
